import { apiClient } from "./apiClient.js";

const API_URL = "/api/students";
const DEFAULT_LIMIT = 10;

export class StudentService {
    constructor(client = apiClient) {
        this.client = client;
        this.cache = new Map();
    }

    async getStudents(limit = DEFAULT_LIMIT) {
        const response = await this.client.get(`${API_URL}?limit=${limit}`);

        if (!response.ok) {
            throw new Error(`Unable to load students: ${response.status}`);
        }

        const students = await response.json();
        this.cacheStudents(students);
        return students;
    }

    async getStudentById(id) {
        if (this.cache.has(id)) {
            return this.cache.get(id);
        }

        const response = await this.client.get(`${API_URL}/${id}`);

        if (!response.ok) {
            return null;
        }

        const student = await response.json();
        this.cache.set(student.rollNo, student);
        return student;
    }

    cacheStudents(students) {
        students.forEach((student) => {
            this.cache.set(student.rollNo, student);
        });
    }

    getPresentStudents(students) {
        return students.filter((student) => student.isPresent === true);
    }

    getAverageMark(student) {
        if (!student.marks || student.marks.length === 0) {
            return 0;
        }

        const total = student.marks.reduce((sum, mark) => sum + mark, 0);
        return Math.round((total / student.marks.length) * 100) / 100;
    }

    formatStudent(student) {
        const average = this.getAverageMark(student);
        return `${student.rollNo} - ${student.name} - Average: ${average}`;
    }
}

export const studentService = new StudentService();

